import{_ as l,a0 as r,w as s,s as m,I as e,x as n,ao as p,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"LFCS 系列第五講：如何在 Linux 中掛載/卸載本地文件系統和網絡文件系統（Samba 和 NFS） | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第五講：如何在 Linux 中掛載/卸載本地文件系統和網絡文件系統（Samba 和 NFS） | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第五講：如何在 Linux 中掛載/卸載本地文件系統和網絡文件系統（Samba 和 NFS） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第五講：如何在 Linux 中掛載/卸載本地文件系統和網絡文件系統（Samba 和 NFS） | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 5 - LFCS--How to Mount or Unmount Local and Network Samba and NFS Filesystems in Linux","title":"LFCS 系列第五講：如何在 Linux 中掛載/卸載本地文件系統和網絡文件系統（Samba 和 NFS）","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 5 - LFCS--How to Mount or Unmount Local and Network Samba and NFS Filesystems in Linux.md","filePath":"[post].md"}'),u={name:"LFCS/Part 5 - LFCS--How to Mount or Unmount Local and Network Samba and NFS Filesystems in Linux.md"};function d(S,t,b,f,w,x){const a=r("Link");return s(),m("div",null,[t[21]||(t[21]=e("h1",{id:"lfcs-系列第五講-如何在-linux-中掛載-卸載本地文件系統和網絡文件系統-samba-和-nfs",tabindex:"-1"},[n("LFCS 系列第五講：如何在 Linux 中掛載/卸載本地文件系統和網絡文件系統（Samba 和 NFS） "),e("a",{class:"header-anchor",href:"#lfcs-系列第五講-如何在-linux-中掛載-卸載本地文件系統和網絡文件系統-samba-和-nfs","aria-label":"Permalink to “LFCS 系列第五講：如何在 Linux 中掛載/卸載本地文件系統和網絡文件系統（Samba 和 NFS）”"},"​")],-1)),t[22]||(t[22]=e("p",null,"Linux 基金會已經發起了一個全新的 LFCS（Linux Foundation Certified Sysadmin，Linux 基金會認證系統管理員）認證，旨在讓來自世界各地的人有機會參加到 LFCS 測試，獲得關於有能力在 Linux 系統中執行中間系統管理任務的認證。該認證包括：維護正在運行的系統和服務的能力、全面監控和分析的能力以及何時向上遊團隊請求支持的決策能力。",-1)),t[23]||(t[23]=e("p",null,[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/10/lfcs-Part-5.png",alt:"Linux Foundation Certified Sysadmin – Part 5"})],-1)),t[24]||(t[24]=e("p",null,[e("em",null,"LFCS 系列第五講")],-1)),t[25]||(t[25]=e("p",null,"請看以下視頻，這裏邊介紹了 Linux 基金會認證程序。",-1)),t[26]||(t[26]=e("p",null,"注：youtube 視頻",-1)),t[27]||(t[27]=e("iframe",{width:"720",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"//www.youtube.com/embed/Y29qZ71Kicg"},null,-1)),t[28]||(t[28]=p(`<p>本講是系列教程中的第五講，在這一講裏邊，我們會解釋如何在 Linux 中掛載/卸載本地和網絡文件系統。這些都是 LFCS 認證中的必備知識。</p><h3 id="掛載文件系統" tabindex="-1">掛載文件系統 <a class="header-anchor" href="#掛載文件系統" aria-label="Permalink to “掛載文件系統”">​</a></h3><p>在個硬盤分好區之後，Linux 需要通過某些方式對硬盤分區上的數據進行訪問。Linux 並不會像 DOS 或者 Windows 那樣給每個硬盤分區分配一個字母來作為盤符，而是將硬盤分區掛載到統一的目錄樹上的掛載點。</p><p>掛載點是一個目錄，掛載是一種訪問分區上文件系統的方法，掛載文件系統實際上是將一個確切的文件系統（比如一個分區）和目錄樹中指定的目錄聯繫起來的過程。</p><p>換句話説，管理存儲設備的第一步就是把設備關聯到文件系統樹。要完成這一步，通常可以這樣：用 mount 命令來進行臨時掛載（用完的時候，使用 umount 命令來卸載），或者通過編輯 /etc/fstab 文件之後重啓系統來永久性掛載，這樣每次開機都會進行掛載。</p><p>不帶任何選項的 mount 命令，可以顯示當前已掛載的文件系統。</p><pre><code># mount
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/check-mounted-filesystems.png" alt="Check Mounted Filesystem in Linux"></p><p><em>檢查已掛載的文件系統</em></p><p>另外，mount 命令通常用來掛載文件系統。其基本語法如下：</p><pre><code># mount -t type device dir -o options
</code></pre><p>該命令會指引內核將在設備上找到的文件系統（如已格式化為指定類型的文件系統）掛載到指定目錄。像這樣的形式，mount 命令不會再到 /etc/fstab 文件中進行確認。</p><p>除非像下面，掛載指定的目錄或者設備：</p><pre><code># mount /dir -o options
或
# mount device -o options
</code></pre><p>mount 命令會嘗試尋找掛載點，如果找不到就會查找設備（上述兩種情況下，mount 命令會在 /etc/fstab 查找相應的設備或掛載點），最後嘗試完成掛載操作（這個通常可以成功執行，除非你的掛載點或者設備正在使用中，或者你調用 mount 命令的時候沒有 root 權限）。</p><p>你可以看到，mount 命令的每行輸出都是如下格式：</p><pre><code>device on directory type (options)
</code></pre><p>例如：</p><pre><code>/dev/mapper/debian-home on /home type ext4 (rw,relatime,user_xattr,barrier=1,data=ordered)
</code></pre><p>讀作：</p><p>設備 dev/mapper/debian-home 掛載在 /home 下，它被格式化為 ext4，並且有以下掛載選項： rw，relatime，user_xattr，barrier=1，data=ordered。</p><p><strong>mount 命令選項</strong></p><p>下面列出 mount 命令的常用選項</p><ul><li>async：允許在將要掛載的文件系統上進行異步 I/O 操作</li><li>auto：標示該文件系統通過 mount -a 命令掛載，與 noauto 相反。</li><li>defaults：該選項相當於 <code>async,auto,dev,exec,nouser,rw,suid</code> 的組合。注意，多個選項必須由逗號隔開並且中間沒有空格。倘若你不小心在兩個選項中間輸入了一個空格，mount 命令會把後邊的字符解釋為另一個參數。</li><li>loop：將鏡像文件（如 .iso 文件）掛載為 loop 設備。該選項可以用來模擬顯示光盤中的文件內容。</li><li>noexec：阻止該文件系統中可執行文件的執行。與 exec 選項相反。</li><li>nouser：阻止任何用户（除 root 用户外） 掛載或卸載文件系統。與 user 選項相反。</li><li>remount：重新掛載文件系統。</li><li>ro：只讀模式掛載。</li><li>rw：讀寫模式掛載。</li><li>relatime：只要訪問時間早於修改時間，就更新文件的的訪問時間。</li><li>user_xattr：允許用户設置和移除可擴展文件系統屬性。</li></ul><p><strong>以 ro 和 noexec 模式掛載設備</strong></p><pre><code># mount -t ext4 /dev/sdg1 /mnt -o ro,noexec
</code></pre><p>在本例中，我們可以看到，在掛載點 /mnt 中嘗試寫入文件或者運行可執行文件都會顯示相應的錯誤信息。</p><pre><code># touch /mnt/myfile
# /mnt/bin/echo “Hi there”
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-Device-Read-Write.png" alt="Mount Device in Read Write Mode"></p><p><em>可讀寫模式掛載設備</em></p><p><strong>以默認模式掛載設備</strong></p><p>以下場景，我們在重新掛載設備的掛載點中，像上例一樣嘗試你寫入文件和運行可執行文件。</p><pre><code># mount -t ext4 /dev/sdg1 /mnt -o defaults
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-Device.png" alt="Mount Device in Linux"></p><p><em>掛載設備</em></p><p>在這個例子中，我們發現寫入文件和命令都完美執行了。</p><h3 id="卸載設備" tabindex="-1">卸載設備 <a class="header-anchor" href="#卸載設備" aria-label="Permalink to “卸載設備”">​</a></h3><p>使用 umount 命令卸載設備，意味着將所有的“在使用”數據全部寫入到文件系統，然後可以安全移除文件系統。請注意，倘若你移除一個沒有事先正確卸載的設備，就會有造成設備損壞和數據丟失的風險。</p><p>也就是説，你必須“離開”設備的塊設備描述符或者掛載點，才能卸載設備。換言之，你的當前工作目錄不能是需要卸載設備的掛載點。否則，系統將返回設備繁忙的提示信息。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Unmount-Device.png" alt="Unmount Device in Linux"></p><p><em>卸載設備</em></p><p>離開需卸載設備的掛載點最簡單的方法就是，運行不帶任何選項的 cd 命令，這樣會回到當前用户的家目錄。</p><h3 id="掛載常見的網絡文件系統" tabindex="-1">掛載常見的網絡文件系統 <a class="header-anchor" href="#掛載常見的網絡文件系統" aria-label="Permalink to “掛載常見的網絡文件系統”">​</a></h3><p>最常用的兩種網絡文件系統是 SMB（Server Message Block，服務器消息塊）和 NFS（Network File System，網絡文件系統）。如果你只向類 Unix 客户端提供共享，用 NFS 就可以了，如果是向 Windows 和其他類 Unix 客户端提供共享服務，就需要用到 Samba 了。</p><p>擴展閲讀</p>`,45)),e("ul",null,[e("li",null,[o(a,{href:"http://www.tecmint.com/setup-samba-server-using-tdbsam-backend-on-rhel-centos-6-3-5-8-and-fedora-17-12/"},{default:i(()=>[...t[0]||(t[0]=[n("Setup Samba Server in RHEL/CentOS and Fedora",-1)])]),_:1})]),e("li",null,[o(a,{href:"http://www.tecmint.com/how-to-setup-nfs-server-in-linux/"},{default:i(()=>[...t[1]||(t[1]=[n("Setting up NFS (Network File System) on RHEL/CentOS/Fedora and Debian/Ubuntu",-1)])]),_:1})])]),t[29]||(t[29]=p(`<p>下面的例子中，假設 Samba 和 NFS 已經在地址為 192.168.0.10 的服務器上架設好了（請注意，架設 NFS 服務器也是 LFCS 考試中需要考核的能力，我們會在後邊中提到）。</p><h4 id="在-linux-中掛載-samba-共享" tabindex="-1">在 Linux 中掛載 Samba 共享 <a class="header-anchor" href="#在-linux-中掛載-samba-共享" aria-label="Permalink to “在 Linux 中掛載 Samba 共享”">​</a></h4><p>第一步：在 Red Hat 以 Debian 系發行版中安裝 samba-client、samba-common 和 cifs-utils 軟件包，如下：</p><pre><code># yum update &amp;&amp; yum install samba-client samba-common cifs-utils
# aptitude update &amp;&amp; aptitude install samba-client samba-common cifs-utils
</code></pre><p>然後運行下列命令，查看服務器上可用的 Samba 共享。</p><pre><code># smbclient -L 192.168.0.10
</code></pre><p>並輸入遠程機器上 root 賬户的密碼。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-Samba-Share.png" alt="Mount Samba Share in Linux"></p><p><em>掛載 Samba 共享</em></p><p>上圖中，已經對可以掛載到我們本地系統上的共享進行高亮顯示。你只需要與一個遠程服務器上的合法用户名及密碼就可以訪問共享了。</p><p>第二步：當掛載有密碼保護的網絡文件系統時候，將你的訪問憑證寫入到 /etc/fstab 文件中並非明智的選擇。你需要將這些信息寫入到具有 600 權限的隱藏文件中，像這樣：</p><pre><code># mkdir /media/samba
# echo “username=samba_username” &gt; /media/samba/.smbcredentials
# echo “password=samba_password” &gt;&gt; /media/samba/.smbcredentials
# chmod 600 /media/samba/.smbcredentials
</code></pre><p>第三步：然後將下面的內容添加到 /etc/fstab 文件中。</p><pre><code># //192.168.0.10/gacanepa /media/samba cifs credentials=/media/samba/.smbcredentials,defaults 0 0
</code></pre>`,14)),e("p",null,[t[3]||(t[3]=n("第四步：現在可以掛載你的 Samba 共享了。手動掛載（mount ",-1)),o(a,{href:"//192.168.0.10/gacanepa%EF%BC%89%E6%88%96%E8%80%85%E9%87%8D%E5%95%93%E7%B3%BB%E7%B5%B1%E4%B8%A6%E6%87%89%E7%94%A8"},{default:i(()=>[...t[2]||(t[2]=[n("//192.168.0.10/gacanepa）或者重啓系統並應用",-1)])]),_:1}),t[4]||(t[4]=n(" /etc/fstab 中相應行來用就掛載都可以。",-1))]),t[30]||(t[30]=p(`<p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-Password-Protect-Samba-Share.png" alt="Mount Password Protect Samba Share"></p><p><em>掛載有密碼保護的 Samba 共享</em></p><h4 id="在-linux-系統中掛載-nfs-共享" tabindex="-1">在 Linux 系統中掛載 NFS 共享 <a class="header-anchor" href="#在-linux-系統中掛載-nfs-共享" aria-label="Permalink to “在 Linux 系統中掛載 NFS 共享”">​</a></h4><p>第一步：在 Red Hat 以 Debian 系發行版中安裝 nfs-common 和 portmap 軟件包。如下：</p><pre><code># yum update &amp;&amp; yum install nfs-utils nfs-utils-lib
# aptitude update &amp;&amp; aptitude install nfs-common
</code></pre><p>第二步：為 NFS 共享創建掛載點。</p><pre><code># mkdir /media/nfs
</code></pre><p>第三步：將下面的內容添加到 /etc/fstab 文件中。</p><p>192.168.0.10:/NFS-SHARE /media/nfs nfs defaults 0 0</p><p>第四步：現在可以掛載你的 Samba 共享了。手動掛載（mount 192.168.0.10:/NFS-SHARE）或者重啓系統並應用 /etc/fstab 中相應行來用就掛載都可以。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Mount-NFS-Share.png" alt="Mount NFS Share in Linux"></p><p><em>掛載 NFS 共享</em></p><h3 id="永久性掛載文件系統" tabindex="-1">永久性掛載文件系統 <a class="header-anchor" href="#永久性掛載文件系統" aria-label="Permalink to “永久性掛載文件系統”">​</a></h3><p>像前面兩個例子那樣，/etc/fstab 控制着Linux如何訪問硬盤分區及可移動設備。/etc/fstab 由六個字段的內容組成，各個字段之間通過一個空格符或者製表符來分開。井號（#）開始的行只是會被忽略的註釋。</p><p>每一行都按照這個格式來寫入：</p><pre><code>&lt;file system&gt; &lt;mount point&gt; &lt;type&gt; &lt;options&gt; &lt;dump&gt; &lt;pass&gt;
</code></pre><p>其中：</p><ul><li>&lt;file system&gt;: 第一個字段指定掛載的設備。大多數發行版本都通過分區的標卷（label）或者 UUID 來指定。這樣做可以避免分區號改變時帶來的錯誤。</li><li>&lt;mount point&gt;: 第二個字段指定掛載點。</li><li>&lt;type&gt; ：文件系統的類型代碼與 mount 命令掛載文件系統時使用的類型代碼是一樣的。通過 auto 類型代碼可以讓內核自動檢測文件系統，這對於可移動設備來説非常方便。注意，該選項可能不是對所有文件系統可用。</li><li>&lt;options&gt;: 一個（或多個）掛載選項。</li><li>&lt;dump&gt;: 你可能把這個字段設置為 0（否則設置為 1），使得系統啓動時禁用 dump 工具（dump 程序曾經是一個常用的備份工具，但現在越來越少用了）對文件系統進行備份。</li><li>&lt;pass&gt;: 這個字段指定啓動系統是是否通過 fsck 來檢查文件系統的完整性。0 表示 fsck 不對文件系統進行檢查。數字越大，優先級越低。因此，根分區（/）最可能使用數字 1，其他所有需要檢查的分區則是以數字 2.</li></ul><p><strong>Mount 命令例示</strong></p><ol><li><p>在系統啓動時，通過 TECMINT 標捲來掛載文件系統，並具備 rw 和 noexec 屬性，你應該將以下語句添加到 /etc/fstab 文件中。</p><p>LABEL=TECMINT /mnt ext4 rw,noexec 0 0</p></li><li><p>若你想在系統啓動時掛載 DVD 光驅中的內容，添加以下語句。</p><p>/dev/sr0 /media/cdrom0 iso9660 ro,user,noauto 0 0</p></li></ol><p>其中 /dev/sr0 為你的 DVD 光驅。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>不用懷疑，在命令列中掛載/卸載本地和網絡文件系統將是你作為系統管理員的日常責任的一部分。同時，你需要掌握 /etc/fstab 文件的編寫。希望本文對你有幫助。隨時在下邊發表評論（或者提問），並分享本文到你的朋友圈。</p><p>參考鏈接</p>`,24)),e("ul",null,[e("li",null,[o(a,{href:"https://training.linuxfoundation.org/certification/LFCS"},{default:i(()=>[...t[5]||(t[5]=[n("About the LFCS",-1)])]),_:1})]),e("li",null,[o(a,{href:"https://training.linuxfoundation.org/certification/why-certify-with-us"},{default:i(()=>[...t[6]||(t[6]=[n("Why get a Linux Foundation Certification?",-1)])]),_:1})]),e("li",null,[o(a,{href:"https://identity.linuxfoundation.org/user?destination=pid/1"},{default:i(()=>[...t[7]||(t[7]=[n("Register for the LFCS exam",-1)])]),_:1})])]),t[31]||(t[31]=e("hr",null,null,-1)),e("p",null,[t[9]||(t[9]=n("via: ",-1)),o(a,{href:"http://www.tecmint.com/mount-filesystem-in-linux/"},{default:i(()=>[...t[8]||(t[8]=[n("http://www.tecmint.com/mount-filesystem-in-linux/",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=n("作者：",-1)),o(a,{href:"http://www.tecmint.com/author/gacanepa/"},{default:i(()=>[...t[10]||(t[10]=[n("Gabriel Cánepa",-1)])]),_:1}),t[14]||(t[14]=n(" 譯者：",-1)),o(a,{href:"https://github.com/GHLandy"},{default:i(()=>[...t[11]||(t[11]=[n("GHLandy",-1)])]),_:1}),t[15]||(t[15]=n(" 校對：",-1)),o(a,{href:"https://github.com/wxy"},{default:i(()=>[...t[12]||(t[12]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[18]||(t[18]=n("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[16]||(t[16]=[n("LCTT",-1)])]),_:1}),t[19]||(t[19]=n(" 原創翻譯，",-1)),o(a,{href:"https://linux.cn/"},{default:i(()=>[...t[17]||(t[17]=[n("Linux中國",-1)])]),_:1}),t[20]||(t[20]=n(" 榮譽推出",-1))])])}const F=l(u,[["render",d]]);export{g as __pageData,F as default};
